0521e572d556c26c010a51c55eba423afcd14352:
query readerSeriesQuery(
  $id: ID!
  $after: String
) {
  series(id: $id) {
    id
    name
    works(after: $after) {
      edges {
        cursor
        position
        node {
          ...readerWork
          manifestations {
            edges {
              cursor
              node {
                ...readerBook
                id
              }
            }
            pageInfo {
              hasNextPage
              hasPreviousPage
              startCursor
              endCursor
            }
          }
          id
        }
      }
      pageInfo {
        hasNextPage
        hasPreviousPage
        startCursor
        endCursor
      }
    }
  }
}

