query readerNodeQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    id
    ... on Manifestation {
      ...readerBook
    }
    ... on Work {
      ...readerWork
    }
    ... on Shelf {
      name
      isSystem
      itemCount
      createdAt
      updatedAt
    }
    ... on Series {
      name
    }
    ... on Viewer {
      displayName
      isChild
    }
  }
}

